<?php
use PHPUnit\Framework\TestCase;
use ServSys\Users\Capabilities;
final class Phase9ServiceCallCloseoutTest extends TestCase {
 public function test_closeout_audit_schema_is_versioned(): void {$boot=file_get_contents(__DIR__.'/../../servsys.php');$schema=file_get_contents(__DIR__.'/../../src/Database/Schema.php');$this->assertStringContainsString("SERVSYS_DB_VERSION', 19",$boot);foreach(array('completed_at datetime NULL','completed_by bigint(20) unsigned NULL','reopened_at datetime NULL','reopened_by bigint(20) unsigned NULL') as $field){$this->assertStringContainsString($field,$schema);}}
 public function test_completion_validates_service_date_work_description_open_time_and_code(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallCloseoutService.php');$this->assertStringContainsString('A valid service date is required before completion.',$p);$this->assertStringContainsString('Services Performed is required before completion.',$p);$this->assertStringContainsString('has_open_activity',$p);$this->assertStringContainsString('Technician work activity is still open.',$p);$this->assertStringContainsString('At least one Completion Code is required before completion.',$p);}
 public function test_completion_revalidates_company_customer_site_and_equipment_relationships(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallCloseoutService.php');$this->assertStringContainsString('Service Call customer/site relationship is invalid.',$p);$this->assertStringContainsString('Service Call equipment relationship is invalid.',$p);$this->assertStringContainsString("['company_id']",$p);$this->assertStringContainsString("['customer_id']",$p);$this->assertStringContainsString("['site_id']",$p);}
 public function test_inventory_and_charges_are_not_closeout_requirements(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallCloseoutService.php');$this->assertStringNotContainsString('ServiceCallChargeRepository',$p);$this->assertStringNotContainsString('ServiceCallInventory',$p);}
 public function test_ordinary_save_cannot_complete_or_edit_completed_call(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallService.php');$this->assertStringContainsString('Use the controlled Service Call completion workflow to complete a call.',$p);$this->assertStringContainsString('Completed Service Calls must be reopened before editing.',$p);}
 public function test_reopen_preserves_children_and_only_updates_workflow_fields(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallCloseoutService.php');$this->assertStringContainsString("'status'=>'open'",$p);$this->assertStringContainsString("'reopened_at'=>\$now",$p);$this->assertStringContainsString("'reopened_by'=>\$user",$p);foreach(array('delete(','replace_equipment','remove(','ServiceCallCharge','Inventory') as $forbidden){$this->assertStringNotContainsString($forbidden,$p);}}
 public function test_closeout_permissions_are_company_scoped(): void {foreach(array(Capabilities::COMPLETE_SERVICE_CALLS,Capabilities::REOPEN_SERVICE_CALLS) as $cap){$this->assertContains($cap,Capabilities::company_capabilities());$this->assertContains($cap,Capabilities::all());}}
 public function test_admin_uses_separate_nonce_protected_closeout_actions(): void {$p=file_get_contents(__DIR__.'/../../src/Admin/ServiceCallsPage.php');$this->assertStringContainsString('admin_post_servsys_complete_service_call',$p);$this->assertStringContainsString('admin_post_servsys_reopen_service_call',$p);$this->assertStringContainsString("check_admin_referer( 'servsys_complete_service_call_' . \$id )",$p);$this->assertStringContainsString("check_admin_referer( 'servsys_reopen_service_call_' . \$id )",$p);$this->assertStringNotContainsString("'completed' => 'Completed'",$p);}
 public function test_service_call_writes_are_company_scoped(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallRepository.php');$this->assertStringContainsString("array( 'id' => \$id, 'company_id' => CompanyContext::current_company_id() )",$p);}
 public function test_installer_upgrade_remains_in_place(): void {$p=file_get_contents(__DIR__.'/../../src/Database/Installer.php');$this->assertStringContainsString('if ( $installed < SERVSYS_DB_VERSION )',$p);$this->assertStringContainsString('dbDelta( $sql )',$p);}
}
